/// 📐️ The independent SQLite engine counts every physical semantic column, including IEEE fields.
fn procedure_independent_semantic_ceiling(source:&ProcedureSnapshot,expected_rows:usize){
 use std::{io::Write,process::{Command,Stdio}};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();
 let database=project(source),bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
 let mut child=Command::new("bun").arg("-e").arg(r####"import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});try{if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const tables=db.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all().map(({name})=>{const columns=db.query('PRAGMA table_info('+name+')').all(),expression=columns.map(({name})=>{const c='"'+name.replaceAll('"','""')+'"';return "CASE typeof("+c+") WHEN 'integer' THEN 8 WHEN 'real' THEN 8 WHEN 'text' THEN length(CAST("+c+" AS BLOB)) WHEN 'blob' THEN length("+c+") WHEN 'null' THEN 0 ELSE NULL END"}).join('+'),r=db.query('SELECT COUNT(*) AS rows,COALESCE(SUM('+expression+'),0) AS bytes FROM '+name).get();return{table:name,columns:columns.length,rows:Number(r.rows),semanticBytes:Number(r.bytes)}});console.log(JSON.stringify(tables));}finally{db.close()}"####).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
 let tables:serde_json::Value=serde_json::from_slice(&output.stdout).unwrap();let tables=tables.as_array().unwrap();let widths:Vec<_>=tables.iter().map(|t|serde_json::json!([t["table"],t["columns"]])).collect();assert_eq!(serde_json::Value::Array(widths),fixture["semanticCells"]["tableWidths"]);let rows=tables.iter().map(|t|t["rows"].as_u64().unwrap()as usize).sum::<usize>();let cells=tables.iter().map(|t|t["semanticBytes"].as_u64().unwrap()as usize).sum::<usize>();assert_eq!(rows,expected_rows);
 let exact=SqliteDatabaseLimits{max_rows:rows,max_value_bytes:cells,..SqliteDatabaseLimits::default()};
 assert_eq!(source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),database);
 let restored=ProcedureSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap();assert_eq!(project(&restored),database);restored.retire_sqlite_snapshot();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<ProcedureSnapshot as store::ArtifactPack>::encode_pack(source)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<ProcedureSnapshot as store::ArtifactDsl>::print_dsl(source))};
  assert_eq!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),payload);
  let decoded=ProcedureSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap();assert_eq!(project(&decoded),database);decoded.retire_sqlite_snapshot();
  for short in[SqliteDatabaseLimits{max_rows:rows-1,..exact},SqliteDatabaseLimits{max_value_bytes:cells-1,..exact}]{assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());assert!(ProcedureSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());}
 }
 for short in[SqliteDatabaseLimits{max_rows:rows-1,..exact},SqliteDatabaseLimits{max_value_bytes:cells-1,..exact}]{assert!(source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());assert!(ProcedureSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());}
}

