 semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("imperative").label("Procedure SQLite declaration").version("0.0.1").package_id("semio:imperative").artifact(crate::declaration().unwrap()).try_build().unwrap();let source=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.imperative.procedure".into(),standard:"1".into(),subset:"*".into()};
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut phases=Vec::new();let bytes=io_export_sqlite_snapshot(&dialect,&source,encoding,SqliteDatabaseLimits{max_rows:4,..SqliteDatabaseLimits::default()},&mut |p|{phases.push(p.phase);true}).await.unwrap().value;let database=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!(database.tables.iter().map(|t|t.rows.len()).sum::<usize>(),4);let restored=io_import_sqlite_snapshot::<ProcedureSnapshot>(&dialect,&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;assert_eq!(restored,source);assert!(!phases.iter().any(|p|matches!(p,SqliteSnapshotPhase::DecodeNative|SqliteSnapshotPhase::EncodeNative)));assert!(io_export_sqlite_snapshot(&dialect,&source,encoding,SqliteDatabaseLimits{max_rows:3,..SqliteDatabaseLimits::default()},&mut |_|true).await.is_err());}
}

